  { id: 'background-h3', name: '更换背景', description: '从现有片段出发，探索新的环境与氛围。', nodes: 21, edited: '昨天 18:26', icon: PhFilmStrip },
]
const visibleWorkflows = computed(() => workflows.filter(item => `${item.name} ${item.description}`.includes(workflowQuery.value.trim())))
const tasks = [
  { id: 'forest', name: '山林之间', image: '/forest-preview.webp', mode: '图生视频', completed: true, time: '今天 09:42', size: '832 × 480', duration: '5 秒', prompt: '清晨的森林，薄雾在山谷间缓缓流动，镜头平稳向前。' },
