    <div class="workflow-list"><article v-for="item in visibleWorkflows" :key="item.id" class="workflow-row"><div class="workflow-icon"><component :is="item.icon" :size="25" /></div><div class="workflow-copy"><h3>{{ item.name }} <span class="badge neutral">H3 试用</span></h3><p>{{ item.description }}</p><span class="row-meta">{{ item.nodes }} 个节点 · {{ item.edited }}</span></div><div class="workflow-actions"><button class="button secondary" @click="emit('action', 'editor', item.id)">打开节点编辑器<PhArrowUpRight :size="16" /></button><button class="icon-button" :aria-label="`保存${item.name}编辑结果`" title="保存编辑结果" @click="emit('action', 'save-workflow', item.id)"><PhFloppyDisk :size="19" /></button><button class="icon-button" :aria-label="`导出${item.name} JSON`" title="导出 JSON" @click="emit('action', 'export-workflow', item.id)"><PhDownloadSimple :size="19" /></button><button class="icon-button" :aria-label="`${item.name}更多操作`" title="更多工作流操作" @click="emit('action', 'workflow-actions', item.id)"><PhDotsThree :size="24" /></button></div></article><p v-if="!visibleWorkflows.length" class="empty">没有找到匹配的工作流，试试其他名称。</p></div>
